# Write a script that automatically detects and utilizes the GraphQL API introspection query to extract the full Schema.

import requests

def fetch_graphql_schema(url):
    # Define the introspection query for GraphQL
    introspection_query = """
    {
        __schema {
            types {
                name
                kind
                description
                fields(includeDeprecated: true) {
                    name
                    description
                    args {
                        name
                        description
                        type { 
                            ...FullType
                        }
                    }
                    type {
                        ...FullType
                    }
                    isDeprecated
                    deprecationReason
                }
            }
        }

        fragment FullType on __Type {
            kind
            name
            ofType {
                ...FullType
            }
        }
    }
    """

    headers = {'Content-Type': 'application/json'}

    # Make the request to the GraphQL API
    response = requests.post(url, json={'query': introspection_query}, headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Query failed with status code {response.status_code}: {response.text}")

# Example usage (replace 'http://example.com/graphql' with the actual GraphQL endpoint URL):
